using namespace std;
int main(){string s,g;cin>>s>>g;
if(s==g){int c[26]={0};for(char x:s)++c[x-'a'];
for(int i=0;i<26;++i)if(c[i]>1){printf("YES\n");return 0;}
printf("NO\n");return 0;}
